export function allocateRevenue(amount: number) {
  return {
    security: amount * 0.2,
    current: amount * 0.5,
    personal: amount * 0.1,
    investment: amount * 0.2
  };
}

export async function validateShift(workerId: string, siteId: string) {
  const hasClearance = await checkSafetyCert(workerId, siteId);
  if (!hasClearance) throw new SecurityError('Clearance denied');
  return clockIn(workerId, siteId, new Date());
}

export async function processTransaction(tx: Transaction) {
  return prisma.$transaction(async (prisma) => {
    const balance = await getBalance(tx.accountId);
    if (balance - tx.amount < 0) throw new Error('Insufficient funds');
    return commitTx(prisma, tx);
  });
}
